1	#!/usr/bin/env node
2	/**
3	 * Node.js port of dataset/base58/test20.py.
4	 *
5	 * The original combines every public base58 entry point in one pass and prints
6	 * twelve values: ten `bytes` objects, one plain integer, and one more `bytes`.
7	 * Each statement below sits at the same source line as the statement it ports,
8	 * so an escaping exception reports the coordinates the reference build reports.
9	 */
10	
11	import { basename } from 'node:path';
12	
13	import { ArgumentParser, SystemExit } from './lib/argparse.mjs';
14	import {
15	  PyException,
16	  formatFrozenTrailer,
17	  formatTraceback,
18	  inFrame,
19	  pyFrame,
20	} from './lib/errors.mjs';
21	import { bytesRepr, utf8Encode } from './lib/pybytes.mjs';
22	import {
23	  b58decode,
24	  b58decodeCheck,
25	  b58decodeInt,
26	  b58encode,
27	  b58encodeCheck,
28	  b58encodeInt,
29	} from './lib/base58/index.mjs';
30	
31	/**
32	 * The module name the reference build names in its tracebacks.  Its frames are
33	 * reported against the original source, which is what the ported line numbers
34	 * below refer to.
35	 */
36	const SOURCE_FILE = 'test20.py';
37	const FROZEN_SCRIPT = 'test20';
38	
39	function buildParser() {
40	  const parser = new ArgumentParser({
41	    prog: basename(process.argv[1] || 'test20.mjs'),
42	  });
43	  parser.addArgument('--a', { type: 'str', required: true });
44	  parser.addArgument('--b', { type: 'str', required: true });
45	  parser.addArgument('--c', { type: 'str', required: true });
46	  parser.addArgument('--d', { type: 'str', required: true });
47	  parser.addArgument('--e', { type: 'str', required: true });
48	  parser.addArgument('--f', { type: 'int', required: true });
49	  parser.addArgument('--g', { type: 'int', required: true });
50	  return parser;
51	}
52	
53	function run() {
54	  const parser = buildParser();
55	  const args = parser.parseArgs(process.argv.slice(2));
56	
57	  /** Evaluate `thunk` as if it were the module-level statement on `line`. */
58	  const atLine = (line, thunk) => inFrame(pyFrame(SOURCE_FILE, line, '<module>'), thunk);
59	
60	  // Final composite scenario: several APIs called in combination.
61	  const enc1 = atLine(15, () => b58encode(utf8Encode(args.a))); // basic encode 1
62	  const dec1 = atLine(16, () => b58decode(args.b)); // basic decode 1
63	  const encCheck1 = atLine(17, () => b58encodeCheck(utf8Encode(args.c))); // checksummed encode 1
64	  const decCheck1 = atLine(18, () => b58decodeCheck(encCheck1)); // checksummed decode 1
65	  const encInt1 = atLine(19, () => b58encodeInt(args.f)); // integer encode 1
66	  const decInt1 = atLine(20, () => b58decodeInt(encInt1)); // integer decode 1
67	  const enc2 = atLine(21, () => b58encode(utf8Encode(args.d))); // basic encode 2
68	  const dec2 = atLine(22, () => b58decode(args.e)); // basic decode 2
69	  const encInt2 = atLine(23, () => b58encodeInt(args.g)); // integer encode 2
70	  const encCheck2 = atLine(24, () => b58encodeCheck(dec1)); // checksum the decoded result
71	  const decCheck2 = atLine(25, () => b58decodeCheck(encCheck2)); // checksummed decode 2
72	  const enc3 = atLine(26, () => b58encode(decCheck2)); // re-encode the checksummed result
73	
74	  console.log(bytesRepr(enc1));
75	  console.log(bytesRepr(dec1));
76	  console.log(bytesRepr(encCheck1));
77	  console.log(bytesRepr(decCheck1));
78	  console.log(bytesRepr(encInt1));
79	  console.log(decInt1.toString());
80	  console.log(bytesRepr(enc2));
81	  console.log(bytesRepr(dec2));
82	  console.log(bytesRepr(encInt2));
83	  console.log(bytesRepr(encCheck2));
84	  console.log(bytesRepr(decCheck2));
85	  console.log(bytesRepr(enc3));
86	}
87	
88	function main() {
89	  try {
90	    run();
91	  } catch (err) {
92	    if (err instanceof SystemExit) {
93	      // Leave the exit code for a natural exit so buffered output still flushes.
94	      process.exitCode = err.code;
95	      return;
96	    }
97	    if (err instanceof PyException) {
98	      process.stderr.write(formatTraceback(err));
99	      process.stderr.write(formatFrozenTrailer(FROZEN_SCRIPT, process.pid));
100	      process.exitCode = 1;
101	      return;
102	    }
103	    throw err;
104	  }
105	}
106	
107	main();
108

1	/**
2	 * `scrub_input`: the coercion every public base58 entry point applies to its
3	 * argument.  A string is encoded as ASCII; a byte sequence passes through.
4	 */
5	
6	import { inFrame } from '../errors.mjs';
7	import { asciiEncode } from '../pybytes.mjs';
8	import { FRAME_SCRUB_INPUT } from './frames.mjs';
9	
10	/** True for the plain integer arrays this port uses to model `bytes`. */
11	export function isByteArray(value) {
12	  return Array.isArray(value);
13	}
14	
15	/**
16	 * Coerce `v` to a byte array.  Encoding a non-ASCII string raises the same
17	 * UnicodeEncodeError the original does, attributed to `scrub_input`.
18	 */
19	export function scrubInput(v) {
20	  if (typeof v === 'string') {
21	    return inFrame(FRAME_SCRUB_INPUT, () => asciiEncode(v));
22	  }
23	  return v;
24	}
25

1	/**
2	 * The byte-string face of base58: `b58encode` and `b58decode`.
3	 *
4	 * Both treat the payload as one big-endian integer, and both carry leading zero
5	 * bytes separately from that integer — a zero byte is invisible to the integer
6	 * but must survive the round trip, so each one is spelled as a leading first
7	 * digit of the alphabet.
8	 */
9	
10	import { inFrame } from '../errors.mjs';
11	import { intFromBytesBE, pyDivmod } from '../pyint.mjs';
12	import { lstripByte, rstripBytes } from '../pybytes.mjs';
13	import { rstripPyStr } from '../pystr.mjs';
14	import { BITCOIN_ALPHABET } from './alphabet.mjs';
15	import { FRAME_B58DECODE_CALL_INT, FRAME_B58DECODE_SCRUB } from './frames.mjs';
16	import { b58decodeInt, b58encodeInt } from './int.mjs';
17	import { scrubInput } from './scrub.mjs';
18	
19	/** Encode a byte array as base58, returning the digits as a byte array. */
20	export function b58encode(v, options = {}) {
21	  const alphabet = options.alphabet || BITCOIN_ALPHABET;
22	  const bytes = scrubInput(v);
23	
24	  const originalLength = bytes.length;
25	  const stripped = lstripByte(bytes, 0x00);
26	  const strippedLength = stripped.length;
27	
28	  const accumulator = intFromBytesBE(stripped);
29	  const digits = b58encodeInt(accumulator, { defaultOne: false, alphabet });
30	
31	  const prefix = [];
32	  for (let i = 0; i < originalLength - strippedLength; i += 1) prefix.push(alphabet[0]);
33	  return prefix.concat(digits);
34	}
35	
36	/** Decode base58 digits (string or byte array) back to a byte array. */
37	export function b58decode(v, options = {}) {
38	  const alphabet = options.alphabet || BITCOIN_ALPHABET;
39	
40	  // Trailing whitespace is dropped while the input is still text, so Unicode
41	  // whitespace is tolerated here even though only ASCII survives the encode.
42	  const trimmed = typeof v === 'string' ? rstripPyStr(v) : rstripBytes(v);
43	  const bytes = inFrame(FRAME_B58DECODE_SCRUB, () => scrubInput(trimmed));
44	
45	  const originalLength = bytes.length;
46	  const stripped = lstripByte(bytes, alphabet[0]);
47	  const strippedLength = stripped.length;
48	
49	  let accumulator = inFrame(FRAME_B58DECODE_CALL_INT, () =>
50	    b58decodeInt(stripped, { alphabet }),
51	  );
52	
53	  const result = [];
54	  while (accumulator > 0n) {
55	    const [quotient, remainder] = pyDivmod(accumulator, 256n);
56	    accumulator = quotient;
57	    result.push(Number(remainder));
58	  }
59	  for (let i = 0; i < originalLength - strippedLength; i += 1) result.push(0x00);
60	  result.reverse();
61	  return result;
62	}
63

1	/**
2	 * The integer face of base58: `b58encode_int` and `b58decode_int`.
3	 */
4	
5	import { PyValueError, inFrame } from '../errors.mjs';
6	import { pyDivmod } from '../pyint.mjs';
7	import { rstripBytes } from '../pybytes.mjs';
8	import { reprChar, rstripPyStr } from '../pystr.mjs';
9	import { BITCOIN_ALPHABET, digitIndex } from './alphabet.mjs';
10	import { FRAME_B58DECODE_INT } from './frames.mjs';
11	import { scrubInput } from './scrub.mjs';
12	
13	/**
14	 * Encode a non-negative integer as base58 digits, returning a byte array.
15	 *
16	 * `defaultOne` reproduces the original's `default_one` flag: zero encodes as a
17	 * single leading digit when set, and as nothing when clear (which is how
18	 * `b58encode` represents an empty payload).
19	 *
20	 * The loop is the original's `while i:` over floor `divmod`.  That means a
21	 * negative input never terminates — as in the reference program, where a
22	 * negative `--f` or `--g` hangs rather than raising.
23	 */
24	export function b58encodeInt(i, options = {}) {
25	  const alphabet = options.alphabet || BITCOIN_ALPHABET;
26	  const defaultOne = options.defaultOne !== false;
27	  const base = BigInt(alphabet.length);
28	
29	  if (i === 0n && defaultOne) return [alphabet[0]];
30	
31	  const digits = [];
32	  let n = i;
33	  while (n !== 0n) {
34	    const [quotient, remainder] = pyDivmod(n, base);
35	    n = quotient;
36	    digits.push(alphabet[Number(remainder)]);
37	  }
38	  digits.reverse();
39	  return digits;
40	}
41	
42	/**
43	 * Decode base58 digits to an integer.  Accepts a string or a byte array; a
44	 * trailing run of whitespace is dropped first, because the alphabet contains no
45	 * space and so cannot mean anything by it.
46	 */
47	export function b58decodeInt(v, options = {}) {
48	  const alphabet = options.alphabet || BITCOIN_ALPHABET;
49	  let value = v;
50	  if (!alphabet.includes(0x20)) {
51	    value = typeof value === 'string' ? rstripPyStr(value) : rstripBytes(value);
52	  }
53	  const bytes = scrubInput(value);
54	  const base = BigInt(alphabet.length);
55	
56	  return inFrame(FRAME_B58DECODE_INT, () => {
57	    let decimal = 0n;
58	    for (const byte of bytes) {
59	      const index = digitIndex(alphabet, byte);
60	      if (index < 0) {
61	        throw new PyValueError(`Invalid character ${reprChar(byte)}`);
62	      }
63	      decimal = decimal * base + BigInt(index);
64	    }
65	    return decimal;
66	  });
67	}
