1	/**
2	 * Python `str` operations that the reference program's behaviour depends on,
3	 * plus the `repr()` spellings that appear inside its error messages.
4	 */
5	
6	import { isPySpace } from './unicode.mjs';
7	
8	/** Code points of a JS string, so indices count characters the way Python does. */
9	export function codePoints(str) {
10	  const out = [];
11	  for (const ch of str) out.push(ch.codePointAt(0));
12	  return out;
13	}
14	
15	/** Python's `str.rstrip()` — trailing Unicode whitespace only. */
16	export function rstripPyStr(str) {
17	  let end = str.length;
18	  while (end > 0) {
19	    const cp = str.codePointAt(end - 1);
20	    // A trailing low surrogate is never whitespace, so code-unit stepping is safe.
21	    if (!isPySpace(cp)) break;
22	    end -= 1;
23	  }
24	  return str.slice(0, end);
25	}
26	
27	/** Python's `str.strip()` — leading and trailing Unicode whitespace. */
28	export function stripPyStr(str) {
29	  let start = 0;
30	  let end = str.length;
31	  while (start < end && isPySpace(str.codePointAt(start))) start += 1;
32	  while (end > start && isPySpace(str.codePointAt(end - 1))) end -= 1;
33	  return str.slice(start, end);
34	}
35	
36	/**
37	 * The `\x`/`\u`/`\U` escape CPython uses for a code point inside a codec error
38	 * message, where non-ASCII is always escaped regardless of printability.
39	 */
40	export function escapeCodePoint(cp) {
41	  if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
42	  if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
43	  return '\\U' + cp.toString(16).padStart(8, '0');
44	}
45	
46	/**
47	 * Python's `repr()` of a one-character string, as interpolated by
48	 * `"Invalid character {!r}"`.  A lone `'` flips the literal to double quotes.
49	 */
50	export function reprChar(cp) {
51	  const quote = cp === 0x27 ? '"' : "'";
52	  let body;
53	  if (cp === 0x5c) body = '\\\\';
54	  else if (cp === 0x09) body = '\\t';
55	  else if (cp === 0x0a) body = '\\n';
56	  else if (cp === 0x0d) body = '\\r';
57	  else if (cp >= 0x20 && cp < 0x7f) body = String.fromCodePoint(cp);
58	  else body = escapeCodePoint(cp);
59	  return quote + body + quote;
60	}
61	
62	/**
63	 * Python's `str.isprintable()`: everything outside the control, format,
64	 * surrogate, private-use, unassigned and separator categories, plus the space.
65	 */
66	const NON_PRINTABLE = /[\p{C}\p{Z}]/u;
67	
68	function isPrintable(cp) {
69	  if (cp === 0x20) return true;
70	  return !NON_PRINTABLE.test(String.fromCodePoint(cp));
71	}
72	
73	/**
74	 * Python's `repr()` of a string, as interpolated by argparse's `%r` in
75	 * `invalid int value: %r`.  Printable characters — including non-ASCII ones —
76	 * are kept verbatim; the rest are escaped.
77	 */
78	export function reprStr(str) {
79	  const cps = codePoints(str);
80	  const quote = cps.includes(0x27) && !cps.includes(0x22) ? '"' : "'";
81	  const quoteCp = quote.charCodeAt(0);
82	  let body = '';
83	  for (const cp of cps) {
84	    if (cp === quoteCp || cp === 0x5c) body += '\\' + String.fromCodePoint(cp);
85	    else if (cp === 0x09) body += '\\t';
86	    else if (cp === 0x0a) body += '\\n';
87	    else if (cp === 0x0d) body += '\\r';
88	    else if (isPrintable(cp)) body += String.fromCodePoint(cp);
89	    else body += escapeCodePoint(cp);
90	  }
91	  return quote + body + quote;
92	}
93

1	/**
2	 * The two Unicode tables Python's own parsing rules depend on:
3	 *
4	 *  - the set of code points for which `str.isspace()` is true, used by
5	 *    `str.rstrip()` (which `base58.b58decode` applies to its input) and by the
6	 *    whitespace skipping in `int(str)`;
7	 *  - the decimal-digit (general category Nd) values accepted by `int(str)`.
8	 */
9	
10	/**
11	 * Inclusive ranges where `str.isspace()` is true.  Note the C0 separators
12	 * 0x1c-0x1f, and that U+180E is *not* whitespace in current Unicode versions.
13	 */
14	const SPACE_RANGES = [
15	  [0x0009, 0x000d],
16	  [0x001c, 0x001f],
17	  [0x0020, 0x0020],
18	  [0x0085, 0x0085],
19	  [0x00a0, 0x00a0],
20	  [0x1680, 0x1680],
21	  [0x2000, 0x200a],
22	  [0x2028, 0x2029],
23	  [0x202f, 0x202f],
24	  [0x205f, 0x205f],
25	  [0x3000, 0x3000],
26	];
27	
28	/** True when Python's `str.isspace()` would be true for this code point. */
29	export function isPySpace(cp) {
30	  if (cp === 0x20) return true;
31	  for (const [lo, hi] of SPACE_RANGES) {
32	    if (cp < lo) return false;
33	    if (cp <= hi) return true;
34	  }
35	  return false;
36	}
37	
38	/** The whitespace bytes stripped by `bytes.rstrip()`: b' \t\n\r\x0b\f'. */
39	const BYTES_SPACE = [0x20, 0x09, 0x0a, 0x0d, 0x0b, 0x0c];
40	
41	/** True when `bytes.rstrip()` would strip this byte. */
42	export function isBytesSpace(byte) {
43	  return BYTES_SPACE.includes(byte);
44	}
45	
46	/**
47	 * First code point of every Unicode decimal-digit block.  Decimal digits are
48	 * always encoded in contiguous, aligned groups of ten in ascending value order,
49	 * so a code point's value is its offset from its block start.
50	 */
51	const DIGIT_BLOCK_STARTS = [
52	  48, 1632, 1776, 1984, 2406, 2534, 2662, 2790, 2918, 3046, 3174, 3302, 3430,
53	  3558, 3664, 3792, 3872, 4160, 4240, 6112, 6160, 6470, 6608, 6784, 6800, 6992,
54	  7088, 7232, 7248, 42528, 43216, 43264, 43472, 43504, 43600, 44016, 65296,
55	  66720, 68912, 69734, 69872, 69942, 70096, 70384, 70736, 70864, 71248, 71360,
56	  71472, 71904, 72016, 72784, 73040, 73120, 73552, 92768, 92864, 93008, 120782,
57	  120792, 120802, 120812, 120822, 123200, 123632, 124144, 125264, 130032,
58	];
59	
60	/**
61	 * Value 0-9 of a Unicode decimal digit, or -1 if the code point is not one.
62	 * `int('٥')` is 5 in Python, so a faithful port cannot special-case ASCII only.
63	 */
64	export function pyDigitValue(cp) {
65	  if (cp >= 0x30 && cp <= 0x39) return cp - 0x30; // fast path for ASCII
66	  let lo = 0;
67	  let hi = DIGIT_BLOCK_STARTS.length - 1;
68	  let start = -1;
69	  while (lo <= hi) {
70	    const mid = (lo + hi) >> 1;
71	    if (DIGIT_BLOCK_STARTS[mid] <= cp) {
72	      start = DIGIT_BLOCK_STARTS[mid];
73	      lo = mid + 1;
74	    } else {
75	      hi = mid - 1;
76	    }
77	  }
78	  if (start < 0) return -1;
79	  const value = cp - start;
80	  return value < 10 ? value : -1;
81	}
82

1	/**
2	 * Python `bytes` modelled as a plain JS array of integers in 0-255, together
3	 * with the codecs that produce them and the `repr()` that prints them.
4	 *
5	 * Byte sequences are deliberately plain arrays: no typed-array or binary-buffer
6	 * abstraction is used anywhere in this port.
7	 */
8	
9	import { PyUnicodeEncodeError } from './errors.mjs';
10	import { escapeCodePoint } from './pystr.mjs';
11	import { isBytesSpace } from './unicode.mjs';
12	
13	/**
14	 * Build the message CPython raises when a codec cannot encode part of a string.
15	 * A maximal run of unencodable characters is reported as one error, and the
16	 * noun is pluralised when the run is longer than one character.
17	 */
18	function encodeErrorMessage(codec, cps, start, end, reason) {
19	  if (end - start === 1) {
20	    return `'${codec}' codec can't encode character ${"'" + escapeCodePoint(cps[start]) + "'"} in position ${start}: ${reason}`;
21	  }
22	  return `'${codec}' codec can't encode characters in position ${start}-${end - 1}: ${reason}`;
23	}
24	
25	/** Python's `str.encode('ascii')`. */
26	export function asciiEncode(str) {
27	  const cps = [];
28	  for (const ch of str) cps.push(ch.codePointAt(0));
29	  for (let i = 0; i < cps.length; i += 1) {
30	    if (cps[i] > 0x7f) {
31	      let end = i + 1;
32	      while (end < cps.length && cps[end] > 0x7f) end += 1;
33	      throw new PyUnicodeEncodeError(
34	        encodeErrorMessage('ascii', cps, i, end, 'ordinal not in range(128)'),
35	      );
36	    }
37	  }
38	  return cps;
39	}
40	
41	/** Python's `str.encode()` — i.e. UTF-8, which rejects surrogates. */
42	export function utf8Encode(str) {
43	  const cps = [];
44	  for (const ch of str) cps.push(ch.codePointAt(0));
45	  const out = [];
46	  for (let i = 0; i < cps.length; i += 1) {
47	    const cp = cps[i];
48	    if (cp >= 0xd800 && cp <= 0xdfff) {
49	      let end = i + 1;
50	      while (end < cps.length && cps[end] >= 0xd800 && cps[end] <= 0xdfff) end += 1;
51	      throw new PyUnicodeEncodeError(
52	        encodeErrorMessage('utf-8', cps, i, end, 'surrogates not allowed'),
53	      );
54	    }
55	    if (cp < 0x80) {
56	      out.push(cp);
57	    } else if (cp < 0x800) {
58	      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
59	    } else if (cp < 0x10000) {
60	      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
61	    } else {
62	      out.push(
63	        0xf0 | (cp >> 18),
64	        0x80 | ((cp >> 12) & 0x3f),
65	        0x80 | ((cp >> 6) & 0x3f),
66	        0x80 | (cp & 0x3f),
67	      );
68	    }
69	  }
70	  return out;
71	}
72	
73	/** Python's `bytes.decode('ascii')`, for turning byte values back into chars. */
74	export function asciiDecode(bytes) {
75	  let out = '';
76	  for (const b of bytes) out += String.fromCharCode(b);
77	  return out;
78	}
79	
80	/** `bytes.lstrip(<single byte>)`. */
81	export function lstripByte(bytes, byte) {
82	  let start = 0;
83	  while (start < bytes.length && bytes[start] === byte) start += 1;
84	  return bytes.slice(start);
85	}
86	
87	/** `bytes.rstrip()` — trailing b' \t\n\r\x0b\f'. */
88	export function rstripBytes(bytes) {
89	  let end = bytes.length;
90	  while (end > 0 && isBytesSpace(bytes[end - 1])) end -= 1;
91	  return bytes.slice(0, end);
92	}
93	
94	/**
95	 * Python's `repr()` of a bytes object, which is what `print(b'...')` writes.
96	 *
97	 * The literal is single quoted unless the value contains a single quote and no
98	 * double quote.  Only `\\`, `\t`, `\n`, `\r` and the delimiter get short
99	 * escapes; every other non-printable byte becomes lowercase `\xNN`.
100	 */
101	export function bytesRepr(bytes) {
102	  let hasSingle = false;
103	  let hasDouble = false;
104	  for (const b of bytes) {
105	    if (b === 0x27) hasSingle = true;
106	    else if (b === 0x22) hasDouble = true;
107	  }
108	  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
109	  let body = '';
110	  for (const b of bytes) {
111	    if (b === quote || b === 0x5c) body += '\\' + String.fromCharCode(b);
112	    else if (b === 0x09) body += '\\t';
113	    else if (b === 0x0a) body += '\\n';
114	    else if (b === 0x0d) body += '\\r';
115	    else if (b >= 0x20 && b < 0x7f) body += String.fromCharCode(b);
116	    else body += '\\x' + b.toString(16).padStart(2, '0');
117	  }
118	  const q = String.fromCharCode(quote);
119	  return 'b' + q + body + q;
120	}
