import { runCase, report } from '/tmp/harness.mjs';

const cases = [
  ['--a','drn1vtp','--b','79KKvfsXwLkag2r3FrZNPdWKv4pvT8DVk','--c','@#$%^&*()','--d','1234567890','--e','2722bfR1UtrSp6ixizzEZeVU9B9hBNcHut8QQ2Q','--f','1000000','--g','82019528'],
  ['--a','Test123','--b','28','--c','TPcTsjvTNHtabUBA','--d','b8aUFiXqDpAs','--e','KAbNUE1LBRuRVeN','--f','0','--g','82019528'],
  ['--a','Test123','--b','Z','--c','2Qu1ga2eTaoXNQzeniuzRQxH1rnQ','--d','AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA','--e','VLKw','--f','262631383','--g','670280744'],
];
const results = cases.map((c) => runCase(c, 60000));
report(results, { showStderr: false });
for (const r of results) console.log(JSON.stringify(r.ref.out));

// Shared case generator for the failure-mode sweep.
export const BASE = {
  a: 'Test123',
  b: '28Zabc',
  c: 'chk',
  d: 'dee',
  e: 'KAbNUE1LBRuRVeN',
  f: '5',
  g: '7',
};

export function argvOf(over = {}) {
  const o = { ...BASE, ...over };
  return ['--a', o.a, '--b', o.b, '--c', o.c, '--d', o.d, '--e', o.e, '--f', o.f, '--g', o.g];
}

const LOOKALIKE = ['0', 'O', 'I', 'l'];
const PUNCT = ['!', '"', "'", '(', ')', '*', '+', ',', '-', '.', '/', ':', ';', '<', '=', '>',
  '?', '@', '[', '\\', ']', '^', '_', '`', '{', '|', '}', '~', '#', '$', '%', '&'];
const SPACE = [' '];
const CTRL = [];
for (let i = 1; i <= 0x1f; i += 1) CTRL.push(String.fromCharCode(i));
CTRL.push('\x7f');

export const ALL_BAD = [...LOOKALIKE, ...PUNCT, ...SPACE, ...CTRL];
export const SMALL_BAD = ['0', 'O', 'I', 'l', ' ', '\t', '\n', '\r', '\x0b', '\x0c',
  '\x1c', '\x1f', '\x7f', '!', '@', '/'];

const VB = '28Zabc'; // valid base58
const VE = 'KAbNUE1LBRuRVeN';

// four placements of `ch` inside `base`
export function placements(base, ch) {
  return [
    ch + base,
    base.slice(0, 3) + ch + base.slice(3),
    base + ch,
    ch,
  ];
}

export function buildCases() {
  const out = [];
  const push = (argv, tag) => out.push({ argv, tag });

  // Group A: bad char in --b (valid --e)
  for (const ch of ALL_BAD) {
    placements(VB, ch).forEach((v, i) => push(argvOf({ b: v }), `A:b:${ch.charCodeAt(0)}:${i}`));
  }
  // Group B: bad char in --e (valid --b)
  for (const ch of SMALL_BAD) {
    placements(VE, ch).forEach((v, i) => push(argvOf({ e: v }), `B:e:${ch.charCodeAt(0)}:${i}`));
  }
  return out;
}

// Generic driver: reads a JSON array of {argv,tag} from argv[2], runs each,
// prints one line per case; failures printed in detail. Writes failures to argv[3].
import { readFileSync, writeFileSync } from 'node:fs';
import { runCase } from '/tmp/harness.mjs';

const cases = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const timeout = Number(process.argv[4] || 30000);
const failures = [];
let pass = 0;
for (const c of cases) {
  const r = runCase(c.argv, timeout);
  if (r.ok) pass += 1;
  else failures.push({ tag: c.tag, argv: c.argv, ref: r.ref, js: r.js });
}
console.log(`${pass}/${cases.length} passed  (${process.argv[2]})`);
for (const f of failures) {
  console.log(`FAIL ${f.tag} argv=${JSON.stringify(f.argv)} refcode=${f.ref.code} jscode=${f.js.code}`);
  console.log(`  refout=${JSON.stringify(f.ref.out)}`);
  console.log(`  jsout =${JSON.stringify(f.js.out)}`);
}
if (process.argv[3]) writeFileSync(process.argv[3], JSON.stringify(failures, null, 1));

