1	/**
2	 * The base58 digit alphabet.
3	 *
4	 * Derived by observation: encoding the integers 0 through 57 one at a time and
5	 * reading back the single digit produced for each yields exactly this order,
6	 * and confirms that `0`, `O`, `I` and `l` are absent.
7	 */
8	
9	export const BITCOIN_ALPHABET_TEXT =
10	  '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
11	
12	/** The alphabet as byte values, mirroring the `bytes` constant in the original. */
13	export const BITCOIN_ALPHABET = (() => {
14	  const bytes = [];
15	  for (let i = 0; i < BITCOIN_ALPHABET_TEXT.length; i += 1) {
16	    bytes.push(BITCOIN_ALPHABET_TEXT.charCodeAt(i));
17	  }
18	  return bytes;
19	})();
20	
21	const INDEX_CACHE = new WeakMap();
22	
23	/**
24	 * Position of `byte` in `alphabet`, or -1 — i.e. `alphabet.index(char)` without
25	 * the linear scan.  Mirrors that lookup failing for unknown digits.
26	 */
27	export function digitIndex(alphabet, byte) {
28	  let table = INDEX_CACHE.get(alphabet);
29	  if (table === undefined) {
30	    table = new Map();
31	    for (let i = 0; i < alphabet.length; i += 1) table.set(alphabet[i], i);
32	    INDEX_CACHE.set(alphabet, table);
33	  }
34	  const index = table.get(byte);
35	  return index === undefined ? -1 : index;
36	}
