import { writeFileSync } from 'node:fs';

const out = [];
const P = (argv, tag) => out.push({ argv, tag });
const VB = '28Zabc';
const VE = 'KAbNUE1LBRuRVeN';
const ok = (o = {}) => {
  const v = { a: 'Test123', b: VB, c: 'chk', d: 'dee', e: VE, f: '5', g: '7', ...o };
  return ['--a', v.a, '--b', v.b, '--c', v.c, '--d', v.d, '--e', v.e, '--f', v.f, '--g', v.g];
};

// J: Unicode whitespace boundary sweep on trailing position of --b / --e
const CPS = [0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x1b, 0x1c, 0x1d, 0x1e, 0x1f, 0x20, 0x21,
  0x7f, 0x84, 0x85, 0x86, 0x9f, 0xa0, 0xa1, 0x167f, 0x1680, 0x1681, 0x180d, 0x180e, 0x180f,
  0x1fff, 0x2000, 0x2005, 0x200a, 0x200b, 0x2027, 0x2028, 0x2029, 0x202a, 0x202e, 0x202f,
  0x2030, 0x205e, 0x205f, 0x2060, 0x2fff, 0x3000, 0x3001, 0xfeff, 0x1f600];
for (const cp of CPS) {
  const ch = String.fromCodePoint(cp);
  P(ok({ b: VB + ch }), `J:b-trail:${cp}`);
  P(ok({ b: ch }), `J:b-only:${cp}`);
  P(ok({ e: VE + ch }), `J:e-trail:${cp}`);
}
// two-of-a-kind and mixed with an ASCII space after
for (const cp of [0x1f, 0xa0, 0x2000, 0x3000, 0x200b]) {
  const ch = String.fromCodePoint(cp);
  P(ok({ b: VB + ch + ' ' }), `J:b-trail-then-sp:${cp}`);
  P(ok({ b: VB + ' ' + ch }), `J:b-sp-then:${cp}`);
  P(ok({ b: VB + ch + 'Z' }), `J:b-then-valid:${cp}`);
}

// K: int() parsing boundary for --f / --g
const INTS = ['5', '05', '+5', ' 5', '5 ', '\t5', '5\n', '\r5\r', '\x0b5', '\x0c5', '\x1c5',
  '\x1f5', '\x855', '\xa05', ' 5', '　5　', '​5', '﻿5', '᠎5',
  '_5', '5_', '1_0', '1__0', '٥', '٥٥', '۵', '५', '০', '௫', '๕', '༥', '၅', '០', '᠕',
  '１２３', '𝟓', '𝟝', '⁵', '½', 'Ⅴ', '一', '十', '5٥', '٥5', '5.', '.5', '', ' ', '+', '-',
  '0b101', '0o17', '0x1f', '1e2', '5j', 'true', 'None', '٥ ', ' ٥ ', '⁠5'];
for (const s of INTS) {
  P(ok({ f: s }), `K:f:${JSON.stringify(s)}`);
}
for (const s of ['5', '٥', '_5', '１２３', '　5　', 'x', '', '5 ', '​5']) {
  P(ok({ g: s }), `K:g:${JSON.stringify(s)}`);
}
// argparse error precedence with each int slot bad and --b bad
for (const s of ['x', '', '_5', '⁵']) {
  P(ok({ b: '0', f: s }), `K:badb-f:${JSON.stringify(s)}`);
  P(ok({ b: 'é', g: s }), `K:bnonascii-g:${JSON.stringify(s)}`);
}
writeFileSync('/tmp/fail-jk.json', JSON.stringify(out));
console.log('cases', out.length);

