import { runCase } from '/tmp/harness.mjs';

const cases = [
  ['--help'],
  ['-h'],
  ['--h'],
  ['--b', '0', '-h'],
  ['--a', 'x', '--b', '28Zabc', '--c', 'c', '--d', 'd', '--e', 'KAbNUE1LBRuRVeN', '--f', '1', '--g', '1', '--help'],
];
for (let round = 1; round <= 3; round += 1) {
  for (const argv of cases) {
    const r = runCase(argv, 60000);
    console.log(`round=${round} argv=${JSON.stringify(argv)} ok=${r.ok} refcode=${r.ref.code} jscode=${r.js.code}`);
    if (!r.ok) {
      const rl = r.ref.out.split('\n');
      const jl = r.js.out.split('\n');
      for (let i = 0; i < Math.max(rl.length, jl.length); i += 1) {
        if (rl[i] !== jl[i]) console.log(`   line ${i + 1}: ref=${JSON.stringify(rl[i])}  js=${JSON.stringify(jl[i])}`);
      }
    }
  }
}

// Driver + expectation checker: also asserts stdout is EMPTY on both sides
// whenever the reference exits non-zero, and records the exit-code histogram.
import { readFileSync, writeFileSync } from 'node:fs';
import { runCase } from '/tmp/harness.mjs';

const cases = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const timeout = Number(process.argv[4] || 40000);
const failures = [];
const anomalies = [];
const hist = {};
let pass = 0;
for (const c of cases) {
  const r = runCase(c.argv, timeout);
  hist[r.ref.code] = (hist[r.ref.code] || 0) + 1;
  if (r.ok) pass += 1;
  else failures.push({ tag: c.tag, argv: c.argv, ref: r.ref, js: r.js });
  if (r.ref.code !== 0 && r.ref.out !== '') {
    anomalies.push(`NONEMPTY-STDOUT-ON-ERROR ${c.tag} ${JSON.stringify(r.ref.out)}`);
  }
  if (r.js.code !== 0 && r.js.out !== '') {
    anomalies.push(`JS-NONEMPTY-STDOUT-ON-ERROR ${c.tag} ${JSON.stringify(r.js.out)}`);
  }
  // stderr comparison ignoring the PYI pid and the prog name
  const scrub = (s) => s.replace(/\[PYI-\d+:/g, '[PYI-N:')
    .replace(/test20_executable/g, 'PROG').replace(/test20\.mjs/g, 'PROG');
  if (scrub(r.ref.err) !== scrub(r.js.err)) {
    anomalies.push(`STDERR-DIFF ${c.tag} argv=${JSON.stringify(c.argv)}\n   ref=${JSON.stringify(r.ref.err)}\n   js =${JSON.stringify(r.js.err)}`);
  }
}
console.log(`${pass}/${cases.length} passed  (${process.argv[2]})  refExitHist=${JSON.stringify(hist)}`);
for (const f of failures) {
  console.log(`FAIL ${f.tag} argv=${JSON.stringify(f.argv)} refcode=${f.ref.code} jscode=${f.js.code}`);
  console.log(`  refout=${JSON.stringify(f.ref.out)}`);
  console.log(`  jsout =${JSON.stringify(f.js.out)}`);
}
for (const a of anomalies) console.log('ANOM ' + a);
if (process.argv[3]) writeFileSync(process.argv[3], JSON.stringify({ failures, anomalies }, null, 1));

import { writeFileSync } from 'node:fs';

const out = [];
const P = (argv, tag) => out.push({ argv, tag });
const VB = '28Zabc';
const VE = 'KAbNUE1LBRuRVeN';
const ok = (o = {}) => {
  const v = { a: 'Test123', b: VB, c: 'chk', d: 'dee', e: VE, f: '5', g: '7', ...o };
  return ['--a', v.a, '--b', v.b, '--c', v.c, '--d', v.d, '--e', v.e, '--f', v.f, '--g', v.g];
};

// L: non-ASCII x whitespace interaction on --b / --e
const NA = ['é', '中', '\u{1f600}', '\xa1', ' ' /* ws */, '\xa0' /* ws */];
const WS = [' ', '\t', '\n', '\xa0', ' ', '　', '\x1f'];
for (const na of NA) {
  for (const w of WS) {
    P(ok({ b: VB + na + w }), `L:b-na-ws:${na.codePointAt(0)}:${w.codePointAt(0)}`);
    P(ok({ b: VB + w + na }), `L:b-ws-na:${na.codePointAt(0)}:${w.codePointAt(0)}`);
  }
  P(ok({ b: na + ' ' }), `L:b-na-only-sp:${na.codePointAt(0)}`);
  P(ok({ b: ' ' + na }), `L:b-sp-na:${na.codePointAt(0)}`);
  P(ok({ e: VE + na + ' ' }), `L:e-na-sp:${na.codePointAt(0)}`);
  P(ok({ e: na + VE }), `L:e-na-first:${na.codePointAt(0)}`);
}
// astral / position accounting in the error message
P(ok({ b: '\u{1f600}é' }), 'L:b-astral-run');
P(ok({ b: '2\u{1f600}8' }), 'L:b-astral-mid');
P(ok({ b: '2\u{1f600}\u{1f601}8' }), 'L:b-astral-run-mid');
P(ok({ b: '2\u{1f600}8é' }), 'L:b-astral-sep');
P(ok({ e: '2\u{1f600}8' }), 'L:e-astral-mid');
P(ok({ b: 'ééé' }), 'L:b-3na');
P(ok({ b: 'é2é2é' }), 'L:b-na-sep');
P(ok({ b: VB + '\xa0\xa0\xa0' }), 'L:b-3nbsp');
P(ok({ b: VB + '\xa0\xa0é' }), 'L:b-2nbsp-na');
P(ok({ b: VB + 'é\xa0\xa0' }), 'L:b-na-2nbsp');

// M: both --b and --e bad, all kind pairs (order decides)
const KINDS = { valid: null, badascii: '0', punct: '!', ctrl: '\x01', space: ' x', nonascii: 'é' };
for (const [kb, vb] of Object.entries(KINDS)) {
  for (const [ke, ve] of Object.entries(KINDS)) {
    const o = {};
    if (vb !== null) o.b = vb + VB;
    if (ve !== null) o.e = ve + VE;
    P(ok(o), `M:${kb}-${ke}`);
  }
}
// N: argparse error paired with each runtime error kind
for (const [kb, vb] of Object.entries(KINDS)) {
  if (vb === null) continue;
  P(ok({ b: vb + VB, f: 'nope' }), `N:b-${kb}-fbad`);
  P(ok({ e: vb + VE, g: 'nope' }), `N:e-${kb}-gbad`);
  P(['--a', 'x', '--b', vb + VB, '--c', 'c', '--d', 'd', '--e', VE, '--g', '1'], `N:b-${kb}-missingf`);
  P(['--a', 'x', '--b', vb + VB, '--c', 'c', '--d', 'd', '--e', VE, '--f', '1', '--g', '1', '--nope'], `N:b-${kb}-unknown`);
}
writeFileSync('/tmp/fail-lmn.json', JSON.stringify(out));
console.log('cases', out.length);

